/**
 * SQL migrations generated by drizzle-kit, embedded at build time.
 * Vite resolves the glob for Orbit Desktop and the tests; the runtime build
 * (scripts/build-runtime.mjs) replaces this module with the same files inlined.
 */
const migrationFiles = import.meta.glob('../../../../drizzle/*.sql', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>

export const MIGRATION_SOURCES: Record<string, string> = migrationFiles
